worked_examples.problem:
What is the exact output of the following C program?

int main() {
    int a[] = {10, 20, 30, 40, 50};
    int *p = a;
    int val1 = *p++;
    int val2 = (*p)++;
    int val3 = *++p;
    printf("%d %d %d %d", val1, val2, val3, a[1]);
    return 0;
}

